	"github.com/user/freelang-evolving-compiler/internal/parser"
	"github.com/user/freelang-evolving-compiler/internal/typesys"
)

func main() {
	code := `let x = true; let y = false; let a = x && y; let b = x || y; let c = !x;`

	// Lex
	l := lexer.New(code)
	tokens := []ast.Token{}
	for {
		tok := l.NextToken()
		if tok.Type == ast.TokenEOF {
			break
		}
		tokens = append(tokens, tok)
	}

	fmt.Println("=== Tokens ===")
	for _, tok := range tokens {
		fmt.Printf("%v: %s\n", tok.Type, tok.Value)
	}

	// Parse
	p := parser.New(code)
	root, err := p.ParseProgram()
	if err != nil {
		fmt.Printf("Parse error: %v\n", err)
		return
	}
	fmt.Println("\n=== AST ===")
	fmt.Printf("Parsed AST with %d statements\n", len(root.Children))

	// Type Check
	tc := typesys.NewTypeChecker()
	errs := tc.Check(root)
	if len(errs) == 0 {
		fmt.Println("✓ Type checking passed")
	} else {
		fmt.Println("Type errors:")
		for _, e := range errs {
			fmt.Printf("  Line %d: %s\n", e.Line, e.Message)
		}
	}

	// IR Generate
	gen := ir.NewGenerator()
	irProg, err := gen.Generate(root)
	if err != nil {
		fmt.Printf("IR error: %v\n", err)
		return
	}
	fmt.Printf("\n=== IR Generated ===\n")
	fmt.Printf("Main instructions: %d\n", len(irProg.Main))
	for i, instr := range irProg.Main {
		fmt.Printf("  [%d] Op=%d\n", i, instr.Op)
	}

	// Code Generation
	cg := codegen.New()
	result := cg.Generate(irProg)
	fmt.Printf("\n=== Code Generation ===\n")
	fmt.Printf("Generated %d bytes, %d lines\n", result.ByteSize, result.LineCount)
	fmt.Println("\nPseudo-assembly:")
	fmt.Println(result.Code)
}
